#dyn-message-theme[data-theme="tmpl-parallax-drift"]  {
  --p-hot:  color-mix(in srgb, var(--primary) 40%, white);
  --p-soft: color-mix(in srgb, var(--primary) 50%, transparent);
  --p-haze: color-mix(in srgb, var(--primary) 24%, transparent);
  --s-hot:  color-mix(in srgb, var(--secondary) 38%, white);
  --s-soft: color-mix(in srgb, var(--secondary) 48%, transparent);
  --s-haze: color-mix(in srgb, var(--secondary) 22%, transparent);
  background: #07060c;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .dyn-stage  {
  background:
    radial-gradient(90cqw 70cqh at 80% 110%, var(--p-haze), transparent 60%),
    radial-gradient(80cqw 60cqh at 8% -8%, var(--s-haze), transparent 58%),
    linear-gradient(180deg, #0c0a14 0%, #07060c 60%, #09080f 100%);
  perspective: 1400px;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .bands  {
   position: absolute;
   inset: 0;
   z-index: 1;
   pointer-events: none;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .band  {
  position: absolute;
   left: -20%;
   width: 140%;
   height: 9cqh;
  background: linear-gradient(90deg,
    transparent,
    color-mix(in srgb, var(--band, var(--primary)) 18%, transparent) 40%,
    transparent);
  filter: blur(10px);
  opacity: 0.45;
  animation: dynParaBand var(--dur, 28s) linear infinite;
  animation-delay: var(--del, 0s);
}
@keyframes dynParaBand  {
  from  {
   transform: translateX(-12%);
   }
  to    {
   transform: translateX(12%);
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .field  {
  position: absolute;
   inset: 0;
   z-index: 4;
  transform-style: preserve-3d;
  pointer-events: none;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .ghost  {
  position: absolute;
  width: 16cqw;
   height: 22cqw;
  border-radius: 0.8cqw;
  overflow: hidden;
  opacity: 0;
  transform: translate3d(var(--x), var(--y), var(--z)) rotateY(var(--ry, -18deg));
  box-shadow: 0 1.4cqh 3cqh rgba(0,0,0,.45);
  filter: saturate(0.85);
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .ghost img  {
  display: block;
   width: 100%;
   height: 100%;
  object-fit: cover;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .ghost::after  {
  content: '';
  position: absolute;
   inset: 0;
  background: linear-gradient(160deg, var(--s-haze), var(--p-haze));
  mix-blend-mode: soft-light;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on .ghost  {
  opacity: var(--op, 0.22);
  animation: dynParaGhostIn calc(var(--reveal-ms) * 0.8) calc(var(--reveal-ms) * var(--gd, 0.1)) both ease;
}
@keyframes dynParaGhostIn  {
  from  {
   opacity: 0;
   filter: blur(12px);
   }
  to    {
   opacity: var(--op, 0.22);
   filter: blur(var(--blur, 2px));
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on.idle .ghost  {
   animation: dynParaGhostDrift var(--gdur, 22s) ease-in-out infinite alternate;
   }
@keyframes dynParaGhostDrift  {
  from  {
   transform: translate3d(var(--x), var(--y), var(--z)) rotateY(var(--ry, -18deg));
   }
  to    {
   transform: translate3d(calc(var(--x) + var(--dx, 4cqw)), calc(var(--y) + var(--dy, -2cqh)), var(--z)) rotateY(calc(var(--ry, -18deg) + 8deg));
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .hero  {
  position: absolute;
   z-index: 10;
  left: 7cqw;
   top: 50%;
  height: 78cqh;
  aspect-ratio: 3 / 4;
  transform: translateY(-50%) rotateY(18deg) rotateX(4deg);
  transform-origin: 20% 50%;
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .frame  {
  position: relative;
   width: 100%;
   height: 100%;
  border-radius: 1.3cqw;
  overflow: hidden;
  background: #0a0910;
  box-shadow:
    0 3cqh 7cqh rgba(0,0,0,.55),
    0 0 0 1px rgba(255,255,255,.1),
    0 0 5cqw var(--p-haze);
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .frame img  {
  display: block;
   width: 100%;
   height: 100%;
  object-fit: cover;
  filter: saturate(1.12) contrast(1.05);
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .frame::before  {
  content: '';
  position: absolute;
   inset: 0;
   pointer-events: none;
  border-radius: inherit;
  box-shadow: inset 0 0 0 2px rgba(255,255,255,.14);
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .frame::after  {
  content: '';
  position: absolute;
   inset: 0;
   pointer-events: none;
  background: linear-gradient(115deg, rgba(255,255,255,.2), transparent 32%, transparent 70%, var(--p-haze));
  mix-blend-mode: overlay;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .plaque,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze  {
  position: absolute;
  left: 44cqw;
   right: 5cqw;
   top: 50%;
  height: 74cqh;
  display: flex;
   flex-direction: column;
   justify-content: center;
  pointer-events: none;
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .plaque  {
  z-index: 12;
  transform: translateY(-50%) rotateY(-8deg);
  transform-origin: 0 50%;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze  {
  z-index: 11;
  transform: translateY(-50%) translateZ(140px);
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-wash  {
  position: absolute;
  left: -10cqw;
   right: 8%;
  top: 6%;
   bottom: 14%;
  background: radial-gradient(ellipse 70% 65% at 28% 42%, var(--p-soft), transparent 72%);
  filter: blur(48px);
  opacity: 0.55;
  pointer-events: none;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .plaque.gone,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze.gone  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .plaque-inner,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-inner  {
  position: relative;
  z-index: 1;
  display: flex;
   flex-direction: column;
  height: 100%;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .msg-fit,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-msg  {
  flex: 1 1 auto;
  height: 0;
  min-height: 0;
  display: flex;
   align-items: center;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .msg-fit  {
   overflow: hidden;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-msg  {
  overflow: visible;
  filter: blur(70px);
  opacity: 0.55;
  transform: translateX(-3cqw);
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .msg-fit span,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-msg span  {
  display: block;
  width: 100%;
  font-family: 'Anton', 'Arial Narrow', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  line-height: 0.9;
  overflow-wrap: normal;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-msg span  {
   color: var(--primary);
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .msg-fit span  {
   color: #fff;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .name-slot,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-name  {
  flex: none;
  height: 16cqh;
  margin-top: 3.2cqh;
  display: flex;
   align-items: center;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .name-slot  {
  padding-top: 2.2cqh;
  border-top: 3px solid color-mix(in srgb, var(--primary) 70%, transparent);
  overflow: hidden;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .name-slot.hidden,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-name.hidden  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .name-fit,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-name  {
  width: 100%;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .name-fit  {
  height: 12.5cqh;
  overflow: hidden;
  display: flex;
   align-items: center;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-name  {
  overflow: visible;
  filter: blur(48px);
  opacity: 0.62;
  transform: translateX(-2cqw);
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .name-fit span,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-name span  {
  display: block;
  width: 100%;
  font-family: 'Syne', sans-serif;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  line-height: 0.95;
  white-space: nowrap;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze-name span  {
   color: var(--secondary);
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .name-fit span  {
   color: var(--s-hot);
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .plaque.no-msg .msg-fit,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze.no-msg .haze-msg  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .plaque.no-msg .name-slot,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze.no-msg .haze-name  {
  flex: 1;
   height: auto;
   margin-top: 0;
   padding-top: 0;
   border: 0;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .plaque.no-msg .name-fit,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze.no-msg .haze-name  {
   height: 28cqh;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .plaque.no-name .name-slot,
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .haze.no-name .haze-name  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"].no-copy .hero  {
  left: 50%;
  transform: translate(-50%, -50%) rotateY(8deg) rotateX(2deg);
}
@keyframes dynParaHeroIn  {
  0%    {
   opacity: 0;
   transform: translateY(-50%) rotateY(46deg) rotateX(8deg) translate3d(-8cqw, 2cqh, -90px) scale(0.9);
   }
  72%   {
   opacity: 1;
   transform: translateY(-50%) rotateY(20deg) rotateX(4.4deg);
   }
  100%  {
   opacity: 1;
   transform: translateY(-50%) rotateY(18deg) rotateX(4deg);
   }
}
@keyframes dynParaHeroInC  {
  0%    {
   opacity: 0;
   transform: translate(-50%, -50%) rotateY(36deg) rotateX(6deg) scale(0.9);
   }
  72%   {
   opacity: 1;
   transform: translate(-50%, -50%) rotateY(9deg) rotateX(2.2deg);
   }
  100%  {
   opacity: 1;
   transform: translate(-50%, -50%) rotateY(8deg) rotateX(2deg);
   }
}
@keyframes dynParaPlaqueIn  {
  0%    {
   opacity: 0;
   transform: translateY(-50%) rotateY(-20deg) translate3d(4cqw, 1cqh, -40px);
   }
  72%   {
   opacity: 1;
   transform: translateY(-50%) rotateY(-9deg);
   }
  100%  {
   opacity: 1;
   transform: translateY(-50%) rotateY(-8deg);
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on .hero  {
   opacity: 1;
   animation: dynParaHeroIn var(--reveal-ms) cubic-bezier(.2,.72,.22,1) both;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"].no-copy.on .hero  {
   animation-name: dynParaHeroInC;
   }
@keyframes dynParaHazeIn  {
  0%    {
   opacity: 0;
   transform: translateY(-50%) translateZ(140px) translate3d(4cqw, 1cqh, 0);
   }
  72%   {
   opacity: 1;
   transform: translateY(-50%) translateZ(140px);
   }
  100%  {
   opacity: 1;
   transform: translateY(-50%) translateZ(140px);
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on .plaque  {
  opacity: 1;
  animation: dynParaPlaqueIn calc(var(--reveal-ms) * 0.82) calc(var(--reveal-ms) * 0.1) cubic-bezier(.2,.72,.22,1) both;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on .haze  {
  opacity: 1;
  animation: dynParaHazeIn calc(var(--reveal-ms) * 0.82) calc(var(--reveal-ms) * 0.1) cubic-bezier(.2,.72,.22,1) both;
}
@keyframes dynParaHeroDrift  {
  0%, 100%  {
   transform: translateY(-50%) rotateY(18deg) rotateX(4deg);
   }
  50%  {
   transform: translateY(calc(-50% - 0.7cqh)) rotateY(22deg) rotateX(2deg);
   }
}
@keyframes dynParaHeroDriftC  {
  0%, 100%  {
   transform: translate(-50%, -50%) rotateY(8deg) rotateX(2deg);
   }
  50%  {
   transform: translate(-50%, calc(-50% - 0.7cqh)) rotateY(11deg) rotateX(1deg);
   }
}
@keyframes dynParaPlaqueDrift  {
  0%, 100%  {
   transform: translateY(-50%) rotateY(-8deg);
   }
  50%  {
   transform: translateY(calc(-50% - 0.55cqh)) rotateY(-6deg);
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on.idle .hero  {
  opacity: 1;
  animation: dynParaHeroDrift 16s ease-in-out infinite;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].no-copy.on.idle .hero  {
   animation-name: dynParaHeroDriftC;
   }
@keyframes dynParaHazeDrift  {
  0%, 100%  {
   transform: translateY(-50%) translateZ(140px);
   }
  50%  {
   transform: translateY(calc(-50% - 0.55cqh)) translateZ(140px);
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on.idle .plaque  {
  opacity: 1;
  animation: dynParaPlaqueDrift 16s ease-in-out infinite;
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on.idle .haze  {
  opacity: 1;
  animation: dynParaHazeDrift 16s ease-in-out infinite;
}
@keyframes dynParaHeroOut  {
  from  {
   opacity: 1;
   transform: translateY(-50%) rotateY(18deg) rotateX(4deg);
   }
  to  {
   opacity: 0;
   transform: translateY(-50%) rotateY(-40deg) rotateX(2deg) translate3d(7cqw, 0, -40px) scale(0.92);
   }
}
@keyframes dynParaHeroOutC  {
  from  {
   opacity: 1;
   transform: translate(-50%, -50%) rotateY(8deg) rotateX(2deg);
   }
  to  {
   opacity: 0;
   transform: translate(-50%, -50%) rotateY(-36deg) scale(0.92);
   }
}
@keyframes dynParaPlaqueOut  {
  from  {
   opacity: 1;
   transform: translateY(-50%) rotateY(-8deg);
   }
  to  {
   opacity: 0;
   transform: translateY(-50%) rotateY(12deg) translate3d(-3cqw, 0, -20px);
   }
}
@keyframes dynParaGhostOut  {
  to  {
   opacity: 0;
   filter: blur(14px);
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on.off .hero  {
   animation: dynParaHeroOut calc(var(--reveal-ms) * 0.5) cubic-bezier(.6,.05,.85,.35) both;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"].no-copy.on.off .hero  {
   animation-name: dynParaHeroOutC;
   }
@keyframes dynParaHazeOut  {
  from  {
   opacity: 1;
   transform: translateY(-50%) translateZ(140px);
   }
  to  {
   opacity: 0;
   transform: translateY(-50%) translateZ(140px) translate3d(-3cqw, 0, 0);
   }
}
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on.off .plaque  {
   animation: dynParaPlaqueOut calc(var(--reveal-ms) * 0.4) both;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on.off .haze  {
   animation: dynParaHazeOut calc(var(--reveal-ms) * 0.4) both;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"].on.off .ghost  {
   animation: dynParaGhostOut 360ms both;
   }
#dyn-message-theme[data-theme="tmpl-parallax-drift"] .vignette  {
  position: absolute;
   inset: 0;
   z-index: 20;
   pointer-events: none;
  background: radial-gradient(120cqw 100cqh at 42% 48%, transparent 55%, rgba(0,0,0,.55) 100%);
}

/* ================================================================
   PORTRAIT CANVAS (1080x1920): restack photo above copy.
   The originals are landscape-designed;
   these overrides keep every
   element inside the portrait design space. (cq units are already
   container-relative and are not converted.)
   ================================================================ */
#dyn-message-theme.dyn-portrait[data-theme="tmpl-parallax-drift"] .hero  {
  height: 42cqh;
   left: calc(50cqw - 15.75cqh);
   top: 26%;
}
#dyn-message-theme.dyn-portrait[data-theme="tmpl-parallax-drift"] .plaque,
#dyn-message-theme.dyn-portrait[data-theme="tmpl-parallax-drift"] .haze  {
  left: 8cqw;
   right: 8cqw;
   top: 73%;
   height: 40cqh;
}

